from pathlib import Path
import re
ROOT=Path(__file__).resolve().parents[1]; failures=[]
def check(ok,msg): print(('PASS' if ok else 'FAIL')+': '+msg); failures.append(msg) if not ok else None
version=(ROOT/'app/version.php').read_text(); php=(ROOT/'app/mini_game.php').read_text(); index=(ROOT/'public/index.php').read_text(); js=(ROOT/'public/js/mini-game.js').read_text(); css=(ROOT/'public/css/mini-game.css').read_text(); run=(ROOT/'tests/run.sh').read_text()
check(re.search(r"const APP_VERSION = '1\.4\.0(?:-dev\.([2-9]|[1-9][0-9]+))?';", version) is not None or re.search(r"const APP_VERSION = '1\.[567]\.0(?:-dev\.[1-9][0-9]*)?';", version) is not None,'Application version retains V1.4-C Game in V1.4 or later');check('RSS Reader Modernization V1.4-' in version or "const APP_VERSION = '1.4.0';" in version or (('RSS Reader Modernization V1.5-' in version or "APP_VERSION_LABEL = 'RSS Reader Modernization 1.5.0'" in version) or 'RSS Reader Modernization V1.6-' in version or "APP_VERSION_LABEL = 'RSS Reader Modernization 1.6.0'" in version or 'RSS Reader Modernization V1.7-' in version),'label identifies a V1.4 or later checkpoint');check('mini_game_icon_quest_initial_board' in php and 'mock_board' not in php,'initial board replaces Mock naming');check("id: 'iq-01'" in js and "id: 'iq-04'" in js,'four fixed Levels are defined');check('function nextEnemyStep' in js and 'queue.shift()' in js,'Enemy uses bounded pathfinding');check('function applyMove' in js and "finishState(next, 'won', 'clear')" in js,'movement and Clear are explicit');check("finishState(next, 'lost', 'enemy')" in js and "finishState(next, 'lost', 'moves')" in js,'Game Over rules are explicit');check('value.gameVersion !== GAME_VERSION' in js,'Storage version is validated');check('validateBestMoves' in js and 'validateStats' in js,'saved scores and statistics are validated');check('innerHTML' not in js and 'textContent' in js,'Storage values never use innerHTML');check("ArrowUp: 'up'" in js and "w: 'up'" in js,'Arrow Key and WASD are supported');check("event.key === 'Escape'" in js,'Escape leaves board interaction');check('data-mini-game-cell-index' in index and 'aria-live="polite"' in index,'playable cells and live status render');check('mini-game-new-game' in index and 'mini-game-direction' in index,'New Game and direction controls render');check('min-width: 44px' in css and 'height: 44px' in css,'44px controls are preserved');check('prefers-reduced-motion' in css,'reduced motion is supported');check('data-dashboard-swipe-ignore="true"' in index,'Dashboard Swipe conflict remains blocked');check('test_v14c_game_runtime.js' in run and 'test_v14c_browser.py' in run,'main runner includes V1.4-C tests');check(not any('v14' in p.name.lower() for p in (ROOT/'database/migrations').glob('*')),'no V1.4 migration is added')
